from PIL import Image
import pathlib

def check_images_in_dir(directory):
    corrupted_files = []
    for class_dir in os.listdir(directory):
        class_path = os.path.join(directory, class_dir)
        if os.path.isdir(class_path):
            for img_file in os.listdir(class_path):
                img_path = os.path.join(class_path, img_file)
                try:
                    with Image.open(img_path) as img:
                        img.verify()
                except Exception as e:
                    corrupted_files.append((img_path, str(e)))
    return corrupted_files

print("Checking training images...")
train_corrupted = check_images_in_dir('data_small/Training')
print(f"Found {len(train_corrupted)} corrupted files in training data")

print("\nChecking testing images...")
test_corrupted = check_images_in_dir('data_small/Testing')
print(f"Found {len(test_corrupted)} corrupted files in testing data")

