    print("\nFirst few corrupted training files:")
    for file, error in train_corrupted[:5]:
        print(f"  {file}: {error}")

if test_corrupted:
    print("\nFirst few corrupted testing files:")
    for file, error in test_corrupted[:5]:
        print(f"  {file}: {error}")"}

