{"code": "import os
from PIL import Image
import shutil

def get_valid_images(directory):
    """Get list of valid image files that can be opened"""
    valid_files = []
    for class_dir in os.listdir(directory):
        class_path = os.path.join(directory, class_dir)
        if os.path.isdir(class_path):
            for img_file in os.listdir(class_path):
                img_path = os.path.join(class_path, img_file)
                try:
                    with Image.open(img_path) as img:
                        img.load()  # Try to load the image
                    valid_files.append(img_path)
                except Exception as e:
                    continue  # Skip corrupted files
    return valid_files

# Create filtered directories
train_filtered_dir = 'data_filtered/Training'
test_filtered_dir = 'data_filtered/Testing'

os.makedirs(train_filtered_dir, exist_ok=True)
os.makedirs(test_filtered_dir, exist_ok=True)

# Copy valid files to new directories
for class_dir in os.listdir('data_small/Training'):
    class_path = os.path.join('data_small/Training', class_dir)
    if os.path.isdir(class_path):
        new_class_path = os.path.join(train_filtered_dir, class_dir)
        os.makedirs(new_class_path, exist_ok=True)
        for img_file in os.listdir(class_path):
            img_path = os.path.join(class_path, img_file)
            try:
                with Image.open(img_path) as img:
                    img.load()
                shutil.copy2(img_path, new_class_path)
            except Exception:
                continue

for class_dir in os.listdir('data_small/Testing'):
    class_path = os.path.join('data_small/Testing', class_dir)
    if os.path.isdir(class_path):
        new_class_path = os.path.join(test_filtered_dir, class_dir)
        os.makedirs(new_class_path, exist_ok=True)
        for img_file in os.listdir(class_path):
            img_path = os.path.join(class_path, img_file)
            try:
                with Image.open(img_path) as img:
                    img.load()
                shutil.copy2(img_path, new_class_path)
            except Exception:
                continue

# Count files in filtered directories
train_counts = {}
for class_dir in os.listdir(train_filtered_dir):
    class_path = os.path.join(train_filtered_dir, class_dir)
    if os.path.isdir(class_path):
        train_counts[class_dir] = len(os.listdir(class_path))

test_counts = {}
for class_dir in os.listdir(test_filtered_dir):
    class_path = os.path.join(test_filtered_dir, class_dir)
    if os.path.isdir(class_path):
        test_counts[class_dir] = len(os.listdir(class_path))

print(f"Train counts: {train_counts}")
print(f"Test counts: {test_counts}")
print(f"Total train: {sum(train_counts.values())}")
print(f"Total test: {sum(test_counts.values())}")"}

