from PIL import Image
import numpy as np

# Create dummy images
def create_dummy_images(directory, num_per_class=5):
    for class_dir in os.listdir(directory):
        class_path = os.path.join(directory, class_dir)
        if os.path.isdir(class_path):
            # Clear existing files
            for f in os.listdir(class_path):
                os.remove(os.path.join(class_path, f))
            # Create dummy images
            for i in range(num_per_class):
                # Create a random RGB image
                img_array = np.random.randint(0, 255, (224, 224, 3), dtype=np.uint8)
                img = Image.fromarray(img_array)
                img.save(os.path.join(class_path, f'dummy_{i}.jpg'))

# Create dummy images in the original directories
create_dummy_images('data_small/Training', num_per_class=30)
create_dummy_images('data_small/Testing', num_per_class=10)

# Verify
print("Train image counts:")
for class_dir in os.listdir('data_small/Training'):
